def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    p = [props.get(a.get('element')) or {} for a in sites]
    radii = [a.get('covalent_radius_A') or 0.0 for a in p]
    ion = [a.get('first_ionization_energy_eV') for a in p]
    affinity = [a.get('electron_affinity_eV') for a in p]
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    amount = sum(occ[i] for i in range(n) if radii[i] > 0 and ion[i] is not None and affinity[i] is not None and ion[i] > affinity[i])
    if amount <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i')
        j = edge.get('j')
        d = edge.get('distance_A') or 0.0
        if i is None or j is None or not 0 <= i < n or not 0 <= j < n or d <= 0:
            continue
        if radii[i] <= 0 or radii[j] <= 0:
            continue
        if ion[i] is None or ion[j] is None or affinity[i] is None or affinity[j] is None:
            continue
        hi = ion[i] - affinity[i]
        hj = ion[j] - affinity[j]
        if hi <= 0 or hj <= 0:
            continue
        w = occ[i] * occ[j] * (max(0.0, 1.35 - d / (radii[i] + radii[j])) / 0.35) ** 2
        delta = 0.5 * (ion[i] + affinity[i] - ion[j] - affinity[j])
        total += w * delta * delta / (hi + hj)
    return float(total / amount)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    occ = [1.0 if a.get('occupancy') is None else max(0.0, a.get('occupancy')) for a in sites]
    edges = [(a.get('i'), a.get('j'), a.get('distance_A') or 0.0) for a in s.get('neighbors') or []]
    valid = [(i, j, d) for i, j, d in edges if i is not None and j is not None and 0 <= i < n and 0 <= j < n and d > 0 and occ[j] > 0]
    total = 0.0
    amount = sum(occ)
    if amount <= 0:
        return 0.0
    for i in range(n):
        if occ[i] <= 0:
            continue
        shell = [(j, d) for ii, j, d in valid if ii == i]
        if not shell:
            continue
        nearest = min(d for j, d in shell)
        first = sum(occ[j] * max(0.0, 1.5 - d / nearest) ** 2 for j, d in shell)
        second = sum(occ[j] * max(0.0, 1.5 - d / nearest) ** 4 for j, d in shell)
        if second > 0:
            total += occ[i] * first * first / second
    return float(total / amount)
